contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, uint amount) public payable {
        require(true, "");
        uint beforeCount = c.proposalCount();
        c.newGrantProposal(recipient, amount);
        uint pid = c.proposalCount();
        assert(pid == beforeCount + 1);
        (address storedRecipient, uint storedAmount) = c.mapPID_grant(pid);
        assert(storedRecipient == recipient && storedAmount == amount);
        // general rule: majority implies quorum for the fresh proposal
        bool majority = c.hasMajority(pid);
        bool quorum = c.hasQuorum(pid);
        assert(!majority || quorum);
    }

    receive() external payable {}
}

