contract InvMutTest {
    C c;
    uint weight;

    constructor(C _c) { c = _c; }

    function run(address proposedAddress, uint w) public {
        require(w > 0 && w < 2 ** 128);
        c.init(address(this), address(this), address(this));
        c.newAddressProposal(proposedAddress, "GRANT");
        uint pid = c.proposalCount();
        weight = w;
        uint got = c.voteProposal(pid);
        uint storedVotes = c.mapPID_votes(pid);
        assert(got == w && storedVotes == w);
    }

    fallback() external payable {
        bytes4 sel = msg.sig;
        if (sel == bytes4(keccak256("getMemberWeight(address)"))) {
            assembly { mstore(0, weight) return(0, 32) }
        } else if (sel == bytes4(keccak256("totalWeight()"))) {
            assembly { mstore(0, 0) return(0, 32) }
        }
        revert("unsupported");
    }

    receive() external payable {}
}

